    fn q16_helpers() {
        assert_eq!(q16_mul(0x20000, 0x30000), 0x60000);
        assert_eq!(q16_div(0x60000, 0x20000), 0x30000);
        assert_eq!(q16_sqrt(0x40000), 0x20000);
        assert_eq!(q16_div(1, 0), FIX_MIN);
    }
